components.css:
.ds-island{width:440px;height:266px;overflow:hidden;background:var(--notch-black,#08090a);color:var(--chalk,#f2f2ec);border-radius:0 0 28px 28px;box-shadow:0 18px 38px rgba(9,10,9,.28),inset 0 1px 0 rgba(255,255,255,.10);padding:17px 20px 16px;box-sizing:border-box;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC","Hiragino Sans GB","Microsoft YaHei","Helvetica Neue",sans-serif;display:flex;flex-direction:column}
.ds-island-head{display:flex;align-items:center;justify-content:space-between;min-height:44px;margin:0 0 8px;font-size:11px;letter-spacing:.08em;color:var(--dust,#b3b8b1)}
.ds-island-collapse{width:44px;height:44px;display:grid;place-items:center;border:0;border-radius:50%;background:transparent;color:inherit;cursor:pointer}
.ds-island-collapse:hover{background:rgba(255,255,255,.1)}
.ds-island-now{display:flex;align-items:center;gap:15px;min-width:0}
.ds-cover{width:80px;height:80px;flex-shrink:0;overflow:hidden;border-radius:6px;background:#e0e5cf;box-shadow:0 6px 14px rgba(0,0,0,.22)}
.ds-track{min-width:0}
.ds-track-title{margin:0;font-size:18px;font-weight:600;line-height:1.35;letter-spacing:-.015em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ds-track-artist{margin:4px 0 0;font-size:12px;color:var(--dust,#b3b8b1)}
.ds-track-lyric{margin:11px 0 0;font-size:13px;line-height:1.5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ds-seek{display:flex;align-items:center;gap:9px;height:44px;font-size:11px;font-variant-numeric:tabular-nums;color:var(--dust,#b3b8b1)}
.ds-seek-line,.ds-vol-line{position:relative;flex:1;height:2px;background:var(--island-rail,#3a3e39)}
.ds-seek-line i,.ds-vol-line i{position:absolute;left:0;top:0;height:2px;background:var(--chalk,#f2f2ec)}
.ds-seek-line b,.ds-vol-line b{position:absolute;top:-3.5px;width:9px;height:9px;margin-left:-4.5px;border-radius:50%;background:var(--chalk,#f2f2ec)}
.ds-transport{display:flex;align-items:center;justify-content:space-between;gap:14px;min-height:44px;margin-top:auto}
.ds-play-row{display:flex;align-items:center;gap:4px}
.ds-ibtn{width:44px;height:44px;display:grid;place-items:center;border:0;border-radius:50%;background:transparent;color:inherit;cursor:pointer}
.ds-ibtn:hover{background:rgba(255,255,255,.1)}
.ds-play{width:44px;height:44px;display:grid;place-items:center;border:0;border-radius:50%;background:var(--chalk,#f2f2ec);color:var(--notch-black,#08090a);cursor:pointer}
.ds-volume{display:flex;align-items:center;gap:0;width:104px}
.ds-volume .ds-ibtn{width:44px;height:44px}
.ds-vol-line{flex:1}

.ds-stamp{display:inline-flex;align-items:center;justify-content:space-between;gap:22px;min-height:54px;padding:0 18px;background:var(--blueprint-blue,#2253dc);color:#fff;border-radius:2px;box-shadow:inset 0 0 0 1px rgba(255,255,255,.3);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC","Hiragino Sans GB","Microsoft YaHei","Helvetica Neue",sans-serif;font-size:15px;font-weight:600;text-decoration:none;box-sizing:border-box;transition:background .2s,transform .2s}
.ds-stamp:hover{background:var(--graphite,#191a19);transform:translateY(-2px)}
.ds-stamp:hover svg{transform:translate(2px,-2px)}
.ds-stamp svg{transition:transform .2s}
.ds-stamp:focus-visible{outline:2px solid var(--graphite,#191a19);outline-offset:3px}

.ds-head-download{display:inline-flex;align-items:center;gap:10px;min-height:44px;padding:0 16px;background:var(--blueprint-blue,#2253dc);color:#fff;border-radius:2px;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC","Hiragino Sans GB","Microsoft YaHei","Helvetica Neue",sans-serif;font-size:14px;font-weight:600;text-decoration:none;transition:background .2s,transform .2s}
.ds-head-download:hover{background:var(--graphite,#191a19);transform:translateY(-1px)}
.ds-head-download:focus-visible{outline:2px solid var(--blueprint-blue,#2253dc);outline-offset:3px}

.ds-text-button{display:inline-flex;align-items:center;gap:10px;min-height:44px;padding:0;border:0;border-bottom:1px solid var(--graphite-soft,#3f443e);background:transparent;color:var(--graphite,#191a19);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC","Hiragino Sans GB","Microsoft YaHei","Helvetica Neue",sans-serif;font-size:13px;font-weight:500;cursor:pointer;transition:color .2s,border-color .2s}
.ds-text-button:hover{color:var(--blueprint-ink,#1b3a9e);border-color:var(--blueprint-ink,#1b3a9e)}
.ds-text-button:focus-visible{outline:2px solid var(--blueprint-blue,#2253dc);outline-offset:3px}

.ds-lyrics{list-style:none;margin:0;padding:0;border-top:1px solid rgba(25,26,25,.46);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC","Hiragino Sans GB","Microsoft YaHei","Helvetica Neue",sans-serif}
.ds-lyrics li{border-bottom:1px solid rgba(25,26,25,.16)}
.ds-lyric{display:grid;grid-template-columns:40px minmax(0,1fr) 44px;align-items:center;gap:14px;width:100%;min-height:74px;padding:11px 0;border:0;background:transparent;color:var(--pencil-grey,#5c605a);text-align:left;cursor:pointer;transition:color .18s}
.ds-lyric:hover{color:var(--graphite,#191a19)}
.ds-lyric.is-current{color:var(--graphite,#191a19)}
.ds-lyric-no{font-size:11px;letter-spacing:.1em;font-variant-numeric:tabular-nums}
.ds-lyric.is-current .ds-lyric-no{color:var(--blueprint-blue,#2253dc)}
.ds-lyric-label{font-size:28px;font-weight:500;line-height:1.35;letter-spacing:-.015em}
.ds-lyric.is-current .ds-lyric-label{font-weight:600}
.ds-lyric-play{display:grid;place-items:center;width:44px;height:44px;border:1px solid rgba(25,26,25,.46);border-radius:50%;color:var(--graphite,#191a19);box-sizing:border-box;transition:background .18s,color .18s,border-color .18s}
.ds-lyric.is-current .ds-lyric-play{background:var(--blueprint-blue,#2253dc);border-color:var(--blueprint-blue,#2253dc);color:#fff}
.ds-lyric:hover .ds-lyric-play{background:var(--graphite,#191a19);border-color:var(--graphite,#191a19);color:var(--drafting-paper,#efede5)}
.ds-lyric:focus-visible{outline:2px solid var(--blueprint-blue,#2253dc);outline-offset:3px}

.ds-player-list{border-top:1px solid rgba(25,26,25,.46);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC","Hiragino Sans GB","Microsoft YaHei","Helvetica Neue",sans-serif}
.ds-player-row{display:grid;grid-template-columns:44px minmax(0,1fr) 40px;align-items:center;gap:12px;width:100%;min-height:76px;padding:10px 0;border:0;border-bottom:1px solid rgba(25,26,25,.16);background:transparent;color:var(--pencil-grey,#5c605a);text-align:left;cursor:pointer;transition:color .18s}
.ds-player-row:hover,.ds-player-row.is-active{color:var(--graphite,#191a19)}
.ds-player-row.is-active .ds-player-no{color:var(--blueprint-ink,#1b3a9e)}
.ds-player-no{font-size:11px;letter-spacing:.1em;font-variant-numeric:tabular-nums}
.ds-player-name{font-size:40px;font-weight:500;line-height:1.2;letter-spacing:-.02em}
.ds-player-row.is-active .ds-player-name{font-weight:600}
.ds-player-arrow{justify-self:end;color:var(--blueprint-ink,#1b3a9e);opacity:0;transform:translateX(-6px);transition:opacity .18s,transform .18s}
.ds-player-row:hover .ds-player-arrow,.ds-player-row.is-active .ds-player-arrow{opacity:1;transform:none}
.ds-player-row:focus-visible{outline:2px solid var(--blueprint-blue,#2253dc);outline-offset:3px}

.ds-toggle-row{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:15px 0;border-top:1px solid rgba(25,26,25,.16);border-bottom:1px solid rgba(25,26,25,.16);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC","Hiragino Sans GB","Microsoft YaHei","Helvetica Neue",sans-serif;cursor:pointer}
.ds-toggle-copy{display:flex;flex-direction:column;gap:3px}
.ds-toggle-title{font-size:15px;font-weight:500;color:var(--graphite,#191a19)}
.ds-toggle-desc{font-size:12px;color:var(--pencil-grey,#5c605a)}
.ds-toggle{appearance:none;width:22px;height:22px;flex-shrink:0;margin:0;border:1px solid rgba(25,26,25,.46);border-radius:0;background:transparent;cursor:pointer;display:grid;place-content:center;transition:background .2s,border-color .2s}
.ds-toggle:checked{background:var(--blueprint-blue,#2253dc);border-color:var(--blueprint-blue,#2253dc)}
.ds-toggle:checked::after{content:"";width:10px;height:5px;border-left:1.5px solid #fff;border-bottom:1.5px solid #fff;transform:translateY(-1px) rotate(-45deg)}
.ds-toggle:focus-visible{outline:2px solid var(--blueprint-blue,#2253dc);outline-offset:2px}

.ds-faq{border-top:1px solid rgba(25,26,25,.46);border-bottom:1px solid rgba(25,26,25,.16);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC","Hiragino Sans GB","Microsoft YaHei","Helvetica Neue",sans-serif}
.ds-faq summary{display:grid;grid-template-columns:44px minmax(0,1fr) 32px;align-items:center;gap:12px;padding:21px 0;list-style:none;font-size:24px;font-weight:500;line-height:1.4;letter-spacing:-.01em;color:var(--graphite,#191a19);cursor:pointer}
.ds-faq summary::-webkit-details-marker{display:none}
.ds-faq summary::after{content:"";justify-self:end;width:14px;height:14px;background:linear-gradient(var(--graphite,#191a19),var(--graphite,#191a19)) center/14px 1px no-repeat,linear-gradient(var(--graphite,#191a19),var(--graphite,#191a19)) center/1px 14px no-repeat;transition:transform .26s}
.ds-faq[open] summary::after{transform:rotate(45deg)}
.ds-faq-no{font-size:11px;letter-spacing:.1em;color:var(--pencil-grey,#5c605a);font-variant-numeric:tabular-nums}
.ds-faq-answer{padding:0 44px 26px 56px;max-width:720px;box-sizing:border-box}
.ds-faq-answer p{margin:0;color:var(--pencil-grey,#5c605a);font-size:15px;line-height:1.7}
.ds-faq-answer strong{display:block;margin-bottom:4px;color:var(--graphite,#191a19);font-weight:500}
.ds-faq-answer span{display:block;font-size:13px;line-height:1.7}

.ds-player-panel{max-width:520px;padding:30px;background:var(--drafting-paper,#efede5);border:1px solid rgba(25,26,25,.46);box-sizing:border-box;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC","Hiragino Sans GB","Microsoft YaHei","Helvetica Neue",sans-serif}
.ds-source{display:flex;align-items:center;gap:15px;padding-bottom:18px;border-bottom:1px solid rgba(25,26,25,.46)}
.ds-source-mark{display:grid;place-items:center;width:58px;height:58px;box-sizing:border-box;border:1px solid rgba(25,26,25,.16);background:#f6f3ea;color:var(--graphite,#191a19)}
.ds-source-name{margin:0;font-size:24px;font-weight:600;line-height:1.2;letter-spacing:-.02em;color:var(--graphite,#191a19)}
.ds-source-status{display:flex;align-items:center;gap:6px;margin:4px 0 0;font-size:12px;color:var(--pencil-grey,#5c605a)}
.ds-source-status i{width:5px;height:5px;border-radius:50%;background:var(--blueprint-blue,#2253dc)}
.ds-caps{margin:0;padding:0}
.ds-caps>div{display:flex;align-items:baseline;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px solid rgba(25,26,25,.16)}
.ds-caps dt{font-size:13px;color:var(--graphite-soft,#3f443e)}
.ds-caps dd{display:flex;align-items:center;gap:7px;margin:0;font-size:12px;font-weight:500;color:var(--graphite,#191a19)}
.ds-caps dd::before{content:"";width:5px;height:5px;background:var(--blueprint-blue,#2253dc)}
.ds-player-note{margin:15px 0 0;min-height:40px;font-size:12px;line-height:1.65;color:var(--pencil-grey,#5c605a)}
.ds-auto{display:flex;align-items:center;gap:10px;min-height:44px;font-size:13px;color:var(--graphite,#191a19);cursor:pointer}
.ds-auto input{appearance:none;width:17px;height:17px;margin:0;border:1px solid rgba(25,26,25,.46);background:transparent;display:grid;place-content:center;cursor:pointer}
.ds-auto input:checked{background:var(--blueprint-blue,#2253dc);border-color:var(--blueprint-blue,#2253dc)}
.ds-auto input:checked::after{content:"";width:8px;height:4px;border-left:1.5px solid #fff;border-bottom:1.5px solid #fff;transform:translateY(-1px) rotate(-45deg)}
.ds-detect-note{margin:0;font-size:12px;line-height:1.6;color:var(--pencil-grey,#5c605a)}
